CREATE TABLE IF NOT EXISTS cell_organization_level_type (id UUID NOT NULL, name VARCHAR(120) NOT NULL, display_order INTEGER NOT NULL, active BOOLEAN NOT NULL, CONSTRAINT pk_cell_organization_level_type PRIMARY KEY (id), CONSTRAINT uk_cell_level_name UNIQUE (name), CONSTRAINT uk_cell_level_order UNIQUE (display_order));
CREATE TABLE IF NOT EXISTS cell_organization_unit (id UUID NOT NULL, name VARCHAR(160) NOT NULL, description TEXT, status INTEGER NOT NULL, level_type_id UUID NOT NULL, parent_unit_id UUID, responsible_id UUID, CONSTRAINT pk_cell_organization_unit PRIMARY KEY (id), CONSTRAINT fk_cell_unit_level FOREIGN KEY (level_type_id) REFERENCES cell_organization_level_type(id), CONSTRAINT fk_cell_unit_parent FOREIGN KEY (parent_unit_id) REFERENCES cell_organization_unit(id), CONSTRAINT fk_cell_unit_responsible FOREIGN KEY (responsible_id) REFERENCES person(id), CONSTRAINT ck_cell_unit_parent CHECK (parent_unit_id IS NULL OR parent_unit_id <> id));
CREATE INDEX IF NOT EXISTS idx_cell_unit_parent ON cell_organization_unit(parent_unit_id);
CREATE TABLE IF NOT EXISTS cell (id UUID NOT NULL, code VARCHAR(80) NOT NULL, name VARCHAR(160) NOT NULL, description TEXT, type INTEGER NOT NULL, status INTEGER NOT NULL, organization_unit_id UUID, meeting_day INTEGER, meeting_time VARCHAR(10), start_date DATE NOT NULL, capacity INTEGER, member_goal INTEGER, visitor_goal INTEGER, multiplication_goal INTEGER, expected_multiplication_date DATE, address VARCHAR(255), neighborhood VARCHAR(160), city_id UUID, latitude NUMERIC(10,7), longitude NUMERIC(10,7), notes TEXT, CONSTRAINT pk_cell PRIMARY KEY (id), CONSTRAINT uk_cell_code UNIQUE (code), CONSTRAINT fk_cell_unit FOREIGN KEY (organization_unit_id) REFERENCES cell_organization_unit(id), CONSTRAINT fk_cell_city FOREIGN KEY (city_id) REFERENCES city(id), CONSTRAINT ck_cell_day CHECK (meeting_day IS NULL OR meeting_day BETWEEN 0 AND 6), CONSTRAINT ck_cell_capacity CHECK (capacity IS NULL OR capacity > 0));
CREATE INDEX IF NOT EXISTS idx_cell_unit ON cell(organization_unit_id);
CREATE TABLE IF NOT EXISTS cell_leadership (id UUID NOT NULL, cell_id UUID NOT NULL, person_id UUID NOT NULL, role INTEGER NOT NULL, start_date DATE NOT NULL, end_date DATE, active BOOLEAN NOT NULL, CONSTRAINT pk_cell_leadership PRIMARY KEY (id), CONSTRAINT fk_cell_leadership_cell FOREIGN KEY (cell_id) REFERENCES cell(id), CONSTRAINT fk_cell_leadership_person FOREIGN KEY (person_id) REFERENCES person(id), CONSTRAINT ck_cell_leadership_dates CHECK (end_date IS NULL OR end_date >= start_date));
CREATE UNIQUE INDEX IF NOT EXISTS uk_cell_active_leadership ON cell_leadership(cell_id, person_id, role) WHERE active = TRUE AND end_date IS NULL;
CREATE INDEX IF NOT EXISTS idx_cell_leadership_person ON cell_leadership(person_id);
CREATE TABLE IF NOT EXISTS cell_member (id UUID NOT NULL, cell_id UUID NOT NULL, person_id UUID NOT NULL, entry_date DATE NOT NULL, exit_date DATE, status INTEGER NOT NULL, role INTEGER NOT NULL, primary_cell BOOLEAN NOT NULL, regular_participant BOOLEAN NOT NULL, under_follow_up BOOLEAN NOT NULL, can_receive_responsibilities BOOLEAN NOT NULL, origin VARCHAR(160), exit_reason TEXT, notes TEXT, CONSTRAINT pk_cell_member PRIMARY KEY (id), CONSTRAINT fk_cell_member_cell FOREIGN KEY (cell_id) REFERENCES cell(id), CONSTRAINT fk_cell_member_person FOREIGN KEY (person_id) REFERENCES person(id), CONSTRAINT ck_cell_member_dates CHECK (exit_date IS NULL OR exit_date >= entry_date));
CREATE UNIQUE INDEX IF NOT EXISTS uk_cell_member_active_link ON cell_member(cell_id, person_id) WHERE status = 0 AND exit_date IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_cell_member_primary_active ON cell_member(person_id) WHERE status = 0 AND exit_date IS NULL AND primary_cell = TRUE;
CREATE INDEX IF NOT EXISTS idx_cell_member_cell ON cell_member(cell_id);
CREATE TABLE IF NOT EXISTS cell_module_settings (id UUID NOT NULL, cell_term VARCHAR(80) NOT NULL, allow_multiple_cells_per_person BOOLEAN NOT NULL, allow_multiple_leadership BOOLEAN NOT NULL, require_report_approval BOOLEAN NOT NULL, require_multiplication_approval BOOLEAN NOT NULL, allow_visitors_without_person BOOLEAN NOT NULL, absence_alert_count INTEGER NOT NULL, visits_for_integration_suggestion INTEGER NOT NULL, late_report_days INTEGER NOT NULL, default_capacity INTEGER NOT NULL, CONSTRAINT pk_cell_module_settings PRIMARY KEY (id));
